module.exports=[722842,a=>{"use strict";let b=(0,a.i(643326).a)("page-borrow-privacy",{title:{th:"ประกาศความเป็นส่วนตัว การยืมอุปกรณ์",en:"Privacy notice for borrowing equipment"},intro:{th:"การยืมอุปกรณ์ดำเนินการโดย อมธ. ท่าพระจันทร์ หน้านี้บอกว่าเราเก็บข้อมูลอะไร เพราะเหตุใด ใครเห็นได้ และเก็บนานเท่าใด",en:"Equipment loans are run by TUSU at Tha Prachan. This page says what we collect, why, who can see it and how long we keep it"},whatHeading:{th:"ข้อมูลที่เราเก็บและเหตุผล",en:"What we collect and why"},what1What:{th:"ชื่อ เบอร์โทรศัพท์ และอีเมล (อีเมลไม่บังคับ)",en:"Your name, mobile number and email address (email is optional)"},what1Why:{th:"เพื่อติดต่อเรื่องการรับและคืนอุปกรณ์ และแจ้งผลการพิจารณา ข้อมูลเหล่านี้เข้ารหัสไว้ และเจ้าหน้าที่เปิดดูได้ก็ต่อเมื่อเลือกแสดงข้อมูล ซึ่งระบบบันทึกทุกครั้ง",en:"To reach you about collecting and returning the equipment and to tell you the decision. They are encrypted, and staff can read them only by choosing to show them, which is logged every time"},what2What:{th:"เลขประจำตัวนักศึกษา และคณะ หรือหน่วยงานที่คุณสังกัด",en:"Your student number and faculty, or the organisation you belong to"},what2Why:{th:"เพื่อยืนยันว่าผู้ยืมเป็นใคร และให้ติดตามอุปกรณ์ที่ไม่ได้คืนได้ เลขประจำตัวและหน่วยงานเข้ารหัสไว้ เราไม่เก็บเลขบัตรนักศึกษาหรือบัตรประชาชนที่ใช้เป็นหลักประกัน",en:"To know who is borrowing, and to follow up equipment that is not returned. The number and organisation are encrypted. We never record the number of the card left as a deposit"},what3What:{th:"ชื่อกิจกรรม สถานที่ใช้ และวัตถุประสงค์ รวมถึงชื่อกลุ่มหรือชมรมที่ยืมแทน",en:"The event, where it will be used, what it is for, and the name of the club or group you borrow for"},what3Why:{th:"เพื่อให้เจ้าหน้าที่พิจารณาคำขอ ข้อมูลนี้ไม่ใช่ข้อมูลส่วนบุคคลของคุณโดยตรง จึงไม่ได้เข้ารหัส แต่แสดงเฉพาะเจ้าหน้าที่ ไม่แสดงต่อสาธารณะ",en:"So staff can decide on the request. This is not personal data about you as such, so it is not encrypted, but only staff see it. It is never shown publicly"},what4What:{th:"รายการอุปกรณ์ จำนวน วันเวลารับและคืน และเวลาที่คุณยอมรับเงื่อนไข",en:"The items and quantities, the collection and return times, and when you accepted the terms"},what4Why:{th:"เพื่อจองอุปกรณ์ไม่ให้ซ้ำกัน และบันทึกว่าคุณยอมรับเงื่อนไขฉบับใดและเมื่อใด แทนการลงลายมือชื่อในแบบฟอร์มกระดาษ",en:"To reserve the equipment so it is not promised twice, and to record which version of the terms you accepted and when, in place of a signature on a paper form"},what5What:{th:"ที่อยู่ไอพีและชนิดของเบราว์เซอร์",en:"Your IP address and browser type"},what5Why:{th:"เพื่อความปลอดภัย จำกัดการใช้งานเกินปกติ และตรวจสอบย้อนหลังว่าใครทำอะไรกับคำขอ เก็บในบันทึกการตรวจสอบ ไม่ใช้ติดตามตัวคุณ",en:"For security, to limit abuse, and to keep a record of who did what on a request. They are kept in the audit log and are not used to track you"},basisHeading:{th:"เหตุผลที่เราใช้ข้อมูล",en:"Why we may use it"},basis:{th:"เราต้องใช้ข้อมูลเหล่านี้เพื่อให้ยืมอุปกรณ์แก่คุณ จึงไม่ขอความยินยอมแยกต่างหาก หากคุณไม่ต้องการให้ข้อมูล เราให้ยืมอุปกรณ์ไม่ได้ ส่วนอีเมลเป็นทางเลือก",en:"We need this information to lend you the equipment, so we do not ask for separate consent. Without it we cannot lend. Your email address is the one optional item"},whoHeading:{th:"ใครเห็นข้อมูลของคุณ",en:"Who can see your data"},who1:{th:"เจ้าหน้าที่ อมธ. ที่ดูแลการยืมอุปกรณ์เท่านั้น และผู้ดูแลระบบ ทุกครั้งที่มีผู้เปิดดูชื่อ เบอร์โทรศัพท์ เลขประจำตัวนักศึกษา หรือหน่วยงานของคุณ ระบบจะบันทึกไว้",en:"Only the TUSU staff who look after equipment loans, and system administrators. Every time someone opens your name, number, student number or organisation, it is logged"},who2:{th:"หน้าเว็บไซต์สาธารณะไม่แสดงคำขอยืมใดเลย ปฏิทินอุปกรณ์แสดงเพียงจำนวนที่ว่าง ไม่แสดงว่าใครยืม",en:"The public website never shows a request. The availability calendar shows only how many are free, never who has them"},who3:{th:"ถ้าคุณขอให้ส่งลิงก์ส่วนตัวทางอีเมล หรือเจ้าหน้าที่แจ้งผลหรือเตือนวันคืนทางอีเมล ผู้ให้บริการอีเมลของเราจะได้รับที่อยู่อีเมลของคุณเพื่อการนั้นเท่านั้น",en:"If you ask us to email your private link, or staff email you the decision or a reminder to return, our email provider receives your address for those messages only"},who4:{th:"เราไม่ขายหรือแบ่งปันข้อมูลของคุณให้ผู้อื่นเพื่อการตลาด",en:"We do not sell your data or share it for marketing"},cookiesHeading:{th:"คุกกี้ที่จำเป็น",en:"Essential cookies"},cookies1Purpose:{th:"รหัสสุ่มที่ช่วยให้เราจำคำตอบที่คุณกรอกไว้ระหว่างหน้า โดยเก็บคำตอบเข้ารหัสไว้บนเซิร์ฟเวอร์ ไม่มีข้อมูลส่วนบุคคลอยู่ในที่อยู่เว็บหรือในคุกกี้",en:"A random code that lets us keep your answers between pages. The answers stay encrypted on our server. No personal data goes in the web address or the cookie"},cookies1Duration:{th:"2 ชั่วโมง",en:"2 hours"},cookies2Purpose:{th:"จำเลขอ้างอิงและรหัสลิงก์ส่วนตัวของคำขอที่คุณเปิดดู เพื่อไม่ให้รหัสค้างอยู่ในที่อยู่เว็บ",en:"Remembers the reference and private link code of the request you opened, so the code does not stay in the web address"},cookies2Duration:{th:"1 ชั่วโมง",en:"1 hour"},cookiesNote:{th:"คุกกี้ทั้งสองจำเป็นต่อการทำงานของบริการ ไม่ใช้ติดตามหรือโฆษณา จึงไม่ต้องขอความยินยอมแยกต่างหาก",en:"Both are needed for the service to work. They are not used for tracking or advertising, so no separate consent is needed"},keepHeading:{th:"เก็บนานเท่าใด",en:"How long we keep it"},keep1:{th:"คำตอบที่ยังไม่ได้ส่ง: ลบเมื่อพ้น 2 ชั่วโมงนับจากการบันทึกครั้งล่าสุด",en:"Answers you have not sent: deleted 2 hours after the last save"},keep2:{th:"หน้ายืนยันที่แสดงลิงก์ส่วนตัว: เก็บไว้ 30 นาทีเท่านั้น แล้วลบ เราแสดงลิงก์นี้อีกไม่ได้",en:"The confirmation page that shows your private link: kept for 30 minutes only, then deleted. We cannot show the link again later"},keep3:{th:"ข้อมูลส่วนบุคคลในคำขอ: ลบหลังคำขอปิดครบ 1 ปี คำขอปิดเมื่อคืนอุปกรณ์ครบ ชดใช้แล้ว ไม่อนุมัติ ยกเลิก หรือไม่มารับ",en:"Personal data in a request: deleted one year after it closes. A request closes when everything is returned, put right, declined, cancelled or not collected"},keep4:{th:"หลังลบแล้ว เรายังเก็บเพียงรายการอุปกรณ์ จำนวน วันเวลา และสถานะของคำขอ โดยไม่มีข้อมูลส่วนบุคคล",en:"After deletion we keep only the items, quantities, times and status of the request, with no personal data"},rightsHeading:{th:"สิทธิ์ของคุณ",en:"Your rights"},rights:{th:"คุณขอดู แก้ไข หรือลบข้อมูลของคุณได้ ติดต่อเจ้าหน้าที่ตามช่องทางท้ายหน้านี้และแจ้งเลขอ้างอิงของคุณ คุณยกเลิกคำขอเองได้จากลิงก์ส่วนตัวจนถึงก่อนรับอุปกรณ์",en:"You can ask to see, correct or delete your data. Contact the desk using the details at the bottom of this page and quote your reference number. You can cancel a request yourself from your private link until you collect"},contactHeading:{th:"ใครเป็นผู้ดูแลข้อมูล",en:"Who is responsible"},contact:{th:"อมธ. ท่าพระจันทร์ เป็นผู้ควบคุมข้อมูลและเป็นผู้ติดต่อด้านการคุ้มครองข้อมูลส่วนบุคคล ช่องทางติดต่ออยู่ท้ายทุกหน้า",en:"TUSU at Tha Prachan is the data controller and the data protection contact. Its contact details are at the bottom of every page"}},{th:"หน้าความเป็นส่วนตัวของการยืมอุปกรณ์",en:"Borrowing privacy page"});a.s(["f",0,b])}];

